INSERT OR IGNORE INTO courses (slug, title, subtitle, intro, audience, status, sort) VALUES ('financial', 'المحاسبة المالية', 'من الصفر لحد القوائم المالية، مع قصة شركة الكريم', 'كريم كان عنده حلم بسيط: شركة صغيرة لتجارة الأجهزة الكهربائية والإلكترونيات. معاه رأس مال محدود، وخبرة في السوق، ومفيش ولا دفتر. في الكورس ده هتمشي جنبه خطوة بخطوة، من أول جنيه دخل "شركة الكريم للتجارة والتوزيع" لحد ما بقى عندها قوائم مالية تتقرا قدام البنك والشريك. كل مستوى فصل من القصة، وكل مشكلة بتقابل كريم درس محاسبي هتطبقه بإيدك وتفهم المنطق اللي وراه.', 'المحاسبين حديثي التخرج والـ Junior، وأصحاب الشركات والبيزنس الناشئ', 'open', 1);
INSERT OR IGNORE INTO plans (course_id, code, name, features, price, show_price, visible) SELECT id, 'basic', 'الباقة الأساسية', '["المادة العلمية PDF لكل المستويات", "امتحانات المستويات والتراكمي", "متابعة مع المحاضر على واتساب", "شهادة إتمام"]', 0, 0, 1 FROM courses WHERE slug = 'financial';
