INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 1, 'البداية: كريم بيفتح الشركة', 'التأسيس، الفروض والمبادئ المحاسبية، معادلة الميزانية، وطبيعة الحسابات ورأس المال.', 'كريم حط فلوسه وفتح الشركة. أول سؤال هيقابله: الفلوس دي بتاعته ولا بتاعة الشركة؟ هنا هنعرف ليه الشركة شخصية مستقلة، وإزاي معادلة الميزانية بتفضل متزنة في كل لحظة.' FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 1, 'امتحان المستوى 1', 10, 50 FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 2, 'كل عملية ليها وشين', 'نظرية القيد المزدوج، الدورة المستندية، والتسجيل في دفتر اليومية.', 'أول شحنة تلاجات وصلت، ومعاها فاتورة وإذن استلام وإيصال دفع. يسجل إيه وفين؟ هنعرف إن كل عملية ليها طرف مدين وطرف دائن، وإن المستند هو اللي بيحمي المحاسب قبل أي حاجة.' FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 2, 'امتحان المستوى 2', 10, 50 FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 3, 'الأرقام بتتكلم', 'الترحيل إلى دفتر الأستاذ العام والترصيد، وإعداد ميزان المراجعة.', 'بعد شهر اليومية اتملت قيود، وكريم عايز يعرف: معايا كام في الخزينة؟ وعليا كام للموردين؟ هنرحل ونرصد ونطلع ميزان المراجعة، أول تقرير يقول لكريم حساباتك موزونة ولا فيه غلطة.' FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 3, 'امتحان المستوى 3', 10, 50 FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 4, 'على مكتب المشتريات', 'دورة المشتريات ومصروفات النقل، والمردودات والمسموحات، والخصومات بأنواعها.', 'مورد بعت شحنة فيها تالف، وتاني عرض خصم لو الدفع خلال 10 أيام، والنقل ليه فاتورة. هنعرف أثر كل ده على تكلفة البضاعة، والفرق بين الخصم التجاري وخصم تعجيل الدفع.' FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 4, 'امتحان المستوى 4', 10, 50 FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 5, 'العميل دايماً على حق.. بس بحساب', 'دورة المبيعات والعملاء، ومردوداتها ومسموحاتها والخصم المسموح به ومصروفات البيع.', 'المبيعات كبرت: كاش وآجل، وعميل رجع غسالة فيها عيب، وتاني طالب خصم. هنسجل دورة المبيعات كاملة، ونعرف مصروفات البيع بتروح فين.' FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 5, 'امتحان المستوى 5', 10, 50 FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 6, 'المخزن: أغلى أصل عند كريم', 'أنظمة المخزون السلعي (الدوري والمستمر) وطرق تسعير المخزون.', 'كريم اشترى نفس موديل التلفزيون بـ 3 أسعار مختلفة. يبقى تكلفة اللي اتباع كام؟ هنقارن الجرد الدوري والمستمر وطرق التسعير، ونشوف أثر كل طريقة على الربح بمنطق IAS 2.' FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 6, 'امتحان المستوى 6', 10, 50 FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 7, 'عربية التوزيع والمعرض الجديد', 'المحاسبة عن الأصول الثابتة الملموسة وغير الملموسة، وطرق إهلاكها، والاستغناء عنها.', 'كريم اشترى عربية توزيع وجهز معرض واشترى برنامج محاسبي. دي مصروفات ولا أصول؟ هنحسب الإهلاك بطرقه، ونعرف نعمل إيه لما نبيع أصل، بمنطق IAS 16 و IAS 38.' FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 7, 'امتحان المستوى 7', 10, 50 FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 8, 'آخر السنة: ساعة الحقيقة', 'التسويات الجردية الشاملة (المقدمات، المستحقات، والمهمات والأدوات).', 'إيجار مدفوع مقدم لسنة، ومرتبات شهر لسه ما اتصرفتش، وأدوات نصها اتستهلك. هنعمل التسويات علشان الربح يبقى حقيقي مش مجرد رقم في الخزينة.' FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 8, 'امتحان المستوى 8', 10, 50 FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 9, 'كريم كسبان ولا خسران؟', 'قيود الإقفال الختامية وإعداد القوائم المالية الكاملة.', 'اللحظة اللي كريم مستنيها: نقفل الحسابات ونطلع القوائم المالية. هنا هيعرف الفرق بين الكاش والربح، وإزاي يقرا شركته زي ما البنك بيقراها.' FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 9, 'امتحان المستوى 9', 10, 50 FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO levels (course_id, num, title, topics, teaser) SELECT id, 10, 'المحاسب اللي بيحمي الشركة', 'الرقابة والعمليات المتقدمة (مذكرة تسوية البنك، المصروفات النثرية، الأوراق التجارية، وتصحيح الأخطاء الدفترية).', 'كشف البنك مش مطابق، والعهدة النثرية محتاجة ضبط، وكمبيالات العملاء قربت تستحق، وقيد قديم طلع غلط. هنا هتمسك أدوات الرقابة اللي بتفرق المحاسب العادي عن اللي الإدارة بتعتمد عليه.' FROM courses WHERE slug = 'financial';
INSERT OR IGNORE INTO exams (course_id, kind, after_level, title, question_count, pass_pct) SELECT id, 'level', 10, 'امتحان المستوى 10', 10, 50 FROM courses WHERE slug = 'financial';
